import{_ as o,o as a,c,a2 as d}from"./chunks/framework.CnJ-JtFX.js";const u=JSON.parse('{"title":"EP.09 插件不是外挂，是引擎留好的正式扩展面","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.09-lowcode-engine-plugins.md","filePath":"comics/EP.09-lowcode-engine-plugins.md","lastUpdated":1792683644000}'),t={name:"comics/EP.09-lowcode-engine-plugins.md"};function i(l,e,r,n,s,p){return a(),c("div",null,[...e[0]||(e[0]=[d('<h1 id="ep-09-插件不是外挂-是引擎留好的正式扩展面" tabindex="-1">EP.09 插件不是外挂，是引擎留好的正式扩展面 <a class="header-anchor" href="#ep-09-插件不是外挂-是引擎留好的正式扩展面" aria-label="Permalink to &quot;EP.09 插件不是外挂，是引擎留好的正式扩展面&quot;">​</a></h1><blockquote><p>对应章节：<a href="./../guide/09-lowcode-engine-plugins">guide/09-lowcode-engine-plugins</a></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><ol><li><strong>困境</strong>：标签君每接一个平台需求——保存、预览、出码——就改一次引擎源码，最后手上有一份无法升级的 fork。</li><li><strong>揭秘</strong>：码叔指出引擎公开了 <code>ctx</code>、骨架、项目模型与 Setter 注册表，插件只要在 <code>init()</code> 里调用这些扩展点，就能挂上自己的能力。</li><li><strong>实证</strong>：像素酱写了一个 <code>LabToolbarPlugin</code>，用 <code>ctx.skeleton.add</code> 在 <code>topArea</code> 加四个按钮，保存走 <code>exportSchema(&quot;save&quot;)</code>，预览与出码各自独立。</li><li><strong>结案</strong>：码叔收束到「机制留在内核，业务放进插件」：扩展点、生命周期、依赖声明三者稳定，平台才能规模化。</li></ol><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="第一格-为什么改内核是条死路" tabindex="-1">第一格：为什么改内核是条死路 <a class="header-anchor" href="#第一格-为什么改内核是条死路" aria-label="Permalink to &quot;第一格：为什么改内核是条死路&quot;">​</a></h3><p>把保存按钮、预览弹层、出码逻辑写进引擎源码，第一版最快。代价出现在升级时：上游修了一个渲染 bug，你无法直接合并，因为你的 fork 里混着业务代码。第二个代价是复用：另一个平台需要不同的保存接口，只能再复制一份。</p><p>插件机制解决的不是「代码放哪」的审美问题，而是升级与复用问题。内核只保留机制——什么时候调用、上下文里有什么、依赖怎么排；业务实现放在插件里，可以按平台替换。</p><p>对应正文：<a href="./../guide/09-lowcode-engine-plugins#原理拆解">原理拆解</a>。</p><h3 id="第二格-插件函数的三个约定" tabindex="-1">第二格：插件函数的三个约定 <a class="header-anchor" href="#第二格-插件函数的三个约定" aria-label="Permalink to &quot;第二格：插件函数的三个约定&quot;">​</a></h3><ul><li><strong>签名</strong>：插件是一个函数，接收 <code>ctx</code>，返回带 <code>init()</code> 的对象。<code>ctx</code> 是引擎上下文，包含 <code>skeleton</code>、<code>project</code>、<code>material</code>、<code>setters</code>、<code>config</code> 等。</li><li><strong>名字</strong>：<code>plugin.pluginName</code> 用于日志、依赖声明与调试。没有名字的插件在报错时很难定位。</li><li><strong>依赖</strong>：<code>plugin.meta.dependencies</code> 声明初始化顺序。业务插件通常依赖初始化插件，因为后者负责注入物料与初始 schema。</li></ul><p><code>init()</code> 是异步的，引擎会依次 <code>await</code>。这也是为什么 <code>setAssets</code> 与 <code>importSchema</code> 要放在初始化插件里，而不是散落在业务插件中。</p><h3 id="第三格-骨架扩展点的四个参数" tabindex="-1">第三格：骨架扩展点的四个参数 <a class="header-anchor" href="#第三格-骨架扩展点的四个参数" aria-label="Permalink to &quot;第三格：骨架扩展点的四个参数&quot;">​</a></h3><p><code>ctx.skeleton.add({ area, type, props, content })</code>：</p><ul><li><code>area</code>：挂到哪个区域，例如 <code>topArea</code>、<code>leftArea</code>、<code>rightArea</code>；</li><li><code>type</code>：面板类型，例如 <code>Panel</code>、<code>Widget</code>；</li><li><code>props</code>：面板属性，例如标题、图标；</li><li><code>content</code>：真正的 React 内容，通常是按钮组。</li></ul><p>四个按钮之所以能并排出现，是因为它们都挂在 <code>topArea</code>，由骨架统一布局。删掉插件，设计器仍然能启动，只是少了这四个入口——这就是「可插拔」的实际含义。</p><h3 id="第四格-保存、预览、出码的共同边界" tabindex="-1">第四格：保存、预览、出码的共同边界 <a class="header-anchor" href="#第四格-保存、预览、出码的共同边界" aria-label="Permalink to &quot;第四格：保存、预览、出码的共同边界&quot;">​</a></h3><p>三者都从 <code>project.exportSchema(&quot;save&quot;)</code> 出发，但用途不同：</p><ul><li><strong>保存</strong>：把 schema 序列化后写入存储，关心的是完整性；</li><li><strong>预览</strong>：把 schema 交给一个轻量渲染器，关心的是运行态；</li><li><strong>出码</strong>：把 schema 转成 JSX 与 import，关心的是可读性与可维护性。</li></ul><p>共同点是「以 schema 为唯一输入」。只要这条边界守住，三个能力可以分别演进，互不影响。反过来，如果预览直接读设计器内部节点，出码直接读 React 实例，三者就会绑死在一起。</p><h2 id="坑点清单" tabindex="-1">坑点清单 <a class="header-anchor" href="#坑点清单" aria-label="Permalink to &quot;坑点清单&quot;">​</a></h2><ol><li><strong>插件第二参数当配置用</strong>：<code>plugins.register(plugin, options)</code> 的 options 会被 <code>preferenceDeclaration</code> 过滤，未声明 preference 时拿到空对象。用闭包传配置。</li><li><strong>忘记 <code>pluginName</code></strong>：报错信息里只有一堆匿名函数，排查成本陡增。</li><li><strong>不声明 <code>meta.dependencies</code></strong>：业务插件可能先于初始化插件执行，读不到 schema。</li><li><strong><code>skeleton.add</code> 的 <code>area</code> 写错</strong>：面板不会报错，只是不出现，容易误判为样式问题。</li><li><strong>预览直接复用设计器节点</strong>：编辑态与运行态耦合，后续改一处会影响两处。</li></ol><h2 id="自测" tabindex="-1">自测 <a class="header-anchor" href="#自测" aria-label="Permalink to &quot;自测&quot;">​</a></h2><details><summary><b>1. 一个 lowcode-engine 插件至少要满足哪些约定？</b></summary><p>插件是一个接收 <code>ctx</code> 的函数，返回带 <code>init()</code> 的对象；需要设置 <code>pluginName</code> 便于调试；如果依赖其他插件，要在 <code>meta.dependencies</code> 中声明。<code>init()</code> 可以异步，引擎会按依赖顺序 <code>await</code>。</p></details><details><summary><b>2. `ctx.skeleton.add` 的四个参数分别是什么？</b></summary><p><code>area</code> 指定挂载区域（如 <code>topArea</code>）；<code>type</code> 指定面板类型（如 <code>Panel</code>）；<code>props</code> 是面板属性（标题、图标等）；<code>content</code> 是实际渲染的 React 内容。四者共同决定面板出现在哪里、长什么样。</p></details><details><summary><b>3. 保存、预览、出码为什么都以 `exportSchema(&quot;save&quot;)` 为入口？</b></summary><p>因为 schema 是设计器的稳定输出，也是运行态与代码生成的最小输入。三者共享同一个导出边界，才能各自演进而不互相绑死；如果直接读内部节点或 React 实例，编辑态与运行态就会耦合。</p></details><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="./../guide/09-lowcode-engine-plugins">第 09 章正文</a></li><li><a href="./../appendix/glossary">术语表</a></li></ul>',28)])])}const g=o(t,[["render",i]]);export{u as __pageData,g as default};
